TLM.f("Sancti/09-12",{"officium":"S. Nominis Beatæ Mariæ Virginis","rule":["vide C11;","Gloria","Credo","Prefatio=Maria=Festivitate"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Ps 44:13; 44:15-16"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut fidéles tui, qui sub sanctíssimæ Vírginis Maríæ Nómine et protectióne lætántur; ejus pia intercessióne a cunctis malis liberéntur in terris, et ad gáudia ætérna perveníre mereántur in cœlis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:23-31"},{"k":"text","la":"Ego quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:26-38"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriel a Deo in civitátem Galilææ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero et páries fílium, et vocábis nomen ejus Jesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David, patris ejus: et regnábit in domo Jacob in ætérnum, et regni ejus non erit finis. Dixit autem María ad Angelum: Quómodo fiet istud, quóniam virum non cognósco? Et respóndens Angelus, dixit ei: Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi. Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei. Et ecce, Elisabeth, cognáta tua, et ipsa concépit fílium in senectúte sua: et hic mensis sextus est illi, quæ vocátur stérilis: quia non erit impossíbile apud Deum omne verbum. Dixit autem María: Ecce ancílla Dómini, fiat mihi secúndum verbum tuum."}],"Offertorium":[{"k":"ref","la":"Luc 1:28; 1:42"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti."},{"k":"macro","name":"Per Dominum"}]},"hr":{"92898c593a318cb8":{"t":"Ps 44, 13 i 15 i 16, Ps 44, 2\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju."},"2538e54e749c0a1c":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da se tvoji vjerni, koji se raduju zbog imena i zaštite presvete Djevice Marije, oslobode po njezinu pobožnom zagovoru od svih zala na zemlji i zavrijede doći u vječnu radost na nebu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da Tvoje vjernike, koji se veseie imenom i zaštitorti presvete Djevice Marije, njezin zagovor izbavi od svih zala na zemlji, te zavrijede doći k vječnim radostima na nebesima, po G. n.","knRef":"Kniewald 1942, str. 704–705 (snimka 353) (OCR)"},"2de5fba36a04c0be":{"t":"Sir 24, 23-31\nČitanje knjige Mudrosti. Ja sam kao loza dala ugodan miris, a cvijeće moje rod je slavan i častan. Ja sam majka lijepe ljubavi, straha, znanja i svetoga ufanja. U meni je sva milina življenja i istine, u meni je sva nada života i kreposti. Dođite k meni svi koji me želite i nasitite se plodova mojih. Jer je duh moj slađi od meda i nasljedstvo je moje slađe od medenoga saća. Uspomena je moja trajna kroz naraštaje. Koji mene blaguju još će gladovati i koji mene piju još će žeđati. Tko mene sluša neće se postidjeti, i koji rade po meni neće griješiti. Koji mene slave imat će život vječni."},"ba7f76728961f78c":{"t":"Blagoslovljena si i časna, Djevo Marijo, koja si bez povrede djevičanstva bila majka Spasiteljeva. Bogorodice Djevo, u tvojem se zatvori krilu i posta čovjek onaj koga sav svijet ne može obuhvatiti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nPoslije porođaja ostala si, Djevice, nepovrijeđena. Bogorodice, zagovaraj nas. <i>Aleluja</i>.","kn":", Blagcislovema si i časna. Djevo Marlj'O, koja se bez povrede čistoće nađe mati Spasiteljeva. Bogorodice Djevo u tvojem se, postavši čovj.ek, zatvori krilu, koga sav svijet ne obuhvata.\n\nAleluja, aleluja. I poslije poroda ostala si neozlijeđena. Djevice, Bogorodice, zagovaraj nas kod Boga, aleluja.","knRef":"Kniewald 1942, str. 700–701 (snimka 351) (OCR)"},"b7fcb7fcf7056bff":{"t":"Lk 1, 26-38\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se i razmišljala je što taj pozdrav znači. Anđeo joj reče: Nemoj se bojati, Marijo, jer si našla milost u Boga: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. Gospodin će mu dati prijestolje njegova oca Davida, i vladat će Jakovljevom kućom dovijeka i njegovu kraljevstvu neće biti svršetka. Marija reče anđelu: Kako će to biti kad ne poznam muža? Anđeo joj odgovori: Duh će Sveti sići na te i sila će te Svevišnjega osjeniti. Zato će se ono Sveto, što ćeš ti roditi, zvati Sin Božji. A evo, i Elizabeta, tvoja rođakinja, i ona je začela sina u svojoj starosti, i njoj koju zovu nerotkinjom ovo je šesti mjesec, jer u Boga nije ništa nemoguće. Marija na to reče: Evo službenice Gospodnje, neka mi bude po riječi tvojoj.","kn":"t Slijedi sveto evanđelje po Luki (1, 26-38). U ono vrijeme posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici zaručenoj s mužem, koji se zvaO' Josip iz kuće Davidove, a djevica se zvala Marija. Kad je anđeo k njoj ušao, reče: Zdravo milosti puna. Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se na ove riječi i razmišljala je, što znači taj pozdrav. A anđeo joj reče; Ne boj se, Marijo, jer si našla milost kod Bega: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. I Gospodin Bog dat će mu prijestolje Davida, njegova oca, i vladat će nad Jakovljevim domom u vijeke, i njegovu kraljevstvu ne će biti kraja. Marija upita anđela: Kako će to biti, kad ja ne (poznam muža? Anđeo joj odgovori: Duh Sveti doći će nad tebe i osjenit će te sila Svevišnjega; zato će i Sveto, koje ćeš ti roditi, biti Sin Božji. I tvoja je rođakinja Elizabeta začela Sv. Ivan Damascenski 27. III. sina u svojoj starosti, i njoj, koja je nerotkinja, ovo je šesti mjesec; jer Bogu nije ništa nemoguće. Na to Marija reče: Evo službenice Gospodnje, neka mi bude po tvojoj riječi.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"9f99f01cc37689c1":{"t":"Lk 1, 28 i 42\nZdravo, Marijo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje.","kn":"(Lk. 1, 28). Zdravo Marijo, milosti puna, Gospodin s Tobom, blagoslovena Ti među ženama, blagosloven plod utrobe Tvoje.","knRef":"Kniewald 1942, str. 38–39 (snimka 20) (OCR)"},"b5b1bdcbf7bad4ad":{"t":"Tvojim smilovanjem, Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvojom milostivošću. Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i' -sadašnju sreću i mir, po' G; n,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"006ab57f0d571d6b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o svetkovini</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca.","kn":"Blaženokrilo Djevice Marije, koje je nosilo Sina vječnoga Oca,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"91ad6f2bf907ac82":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, okrepe našega spasenja, molimo te, da nas svuda štiti zagovor blažene Marije vazda Djevice kojoj smo na čast prinijeli ove žrtve tvojemu veličanstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, okrepe našega spasenja, molimo, da nas zakrili zaištita blažene Marije, vazda Djevice, kojoj smo na počast ovo prinijeli Tvojem veličanstvu, po G. n.","knRef":"Kniewald 1942, str. 704–705 (snimka 353) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
